// src/index.ts
import { randomUUID as randomUUID2 } from "node:crypto";
import { createOpenAICompatible } from "@ai-sdk/openai-compatible";
import { Plugin } from "@opencode/plugin";

// src/catalog.ts
import { createHash, randomUUID } from "node:crypto";
import { constants } from "node:fs";
import { mkdir, open, rename, rm, writeFile } from "node:fs/promises";
import { homedir } from "node:os";
import { join } from "node:path";
var efforts = ["none", "minimal", "low", "medium", "high", "xhigh", "max", "ultra"];
var modalities = ["text", "image", "audio", "video", "pdf"];
var fallbackContext = 8192;
var fallbackOutput = 4096;
var unsupportedStatuses = [400, 404, 406, 422, 501];
function record(value, message = "Invalid CLIProxyAPI catalog") {
  if (typeof value !== "object" || value === null || Array.isArray(value))
    throw new Error(message);
  return value;
}
function stringOption(value, name) {
  if (value === undefined)
    return;
  if (typeof value !== "string" || value.trim() === "")
    throw new Error(`Invalid ${name} option`);
  return value;
}
function providerID(value) {
  const id = stringOption(value, "providerId") ?? "cliproxyapi";
  if (!/^[a-zA-Z0-9][a-zA-Z0-9._-]*$/.test(id))
    throw new Error("Invalid providerId option");
  return id;
}
function normalizeBaseUrl(value) {
  let url;
  try {
    url = new URL(value);
  } catch {
    throw new Error("Invalid CLIProxyAPI base URL");
  }
  if (!["https:", "http:"].includes(url.protocol) || url.username || url.password || /[?#]/.test(value)) {
    throw new Error("CLIProxyAPI requires an HTTP(S) base URL without credentials, query, or fragment");
  }
  const prefix = url.pathname.replace(/\/+$/, "").replace(/(?:\/v1)+$/, "").replace(/\/+$/, "");
  return url.origin + prefix + "/v1";
}
function resolveConnection(options, env = process.env) {
  const baseUrl = stringOption(options.baseUrl, "baseUrl") ?? env.CLIPROXYAPI_BASE_URL;
  const apiKey = stringOption(options.apiKey, "apiKey") ?? env.CLIPROXYAPI_API_KEY;
  if (!baseUrl || !apiKey)
    throw new Error("Set CLIPROXYAPI_BASE_URL and CLIPROXYAPI_API_KEY or pass options");
  if (!/^[A-Za-z0-9._~+/-]+=*$/.test(apiKey))
    throw new Error("Invalid CLIProxyAPI bearer token");
  return { baseUrl: normalizeBaseUrl(baseUrl), apiKey };
}
function defaultCacheDir(packageName) {
  const root = process.env.XDG_CACHE_HOME || join(homedir(), ".cache");
  return join(root, packageName);
}
function gatewayFetch({ baseUrl, apiKey }, fetcher = fetch) {
  const origin = new URL(baseUrl).origin;
  return (input, init) => {
    const url = new URL(input instanceof Request ? input.url : input);
    if (url.origin !== origin || url.username || url.password)
      throw new Error("CLIProxyAPI request changed origin");
    const headers = new Headers(init?.headers ?? (input instanceof Request ? input.headers : undefined));
    headers.set("authorization", `Bearer ${apiKey}`);
    return fetcher(input, { ...init, headers, redirect: "error" });
  };
}
function getID(value, seen) {
  if (typeof value !== "string" || !/^[A-Za-z0-9][A-Za-z0-9._:+@-]*(?:\/[A-Za-z0-9][A-Za-z0-9._:+@-]*)*$/.test(value)) {
    throw new Error("Invalid CLIProxyAPI model ID");
  }
  if (seen.has(value))
    throw new Error("Duplicate CLIProxyAPI model ID");
  seen.add(value);
  return value;
}
function nameOf(value, id) {
  if (value == null)
    return id;
  if (typeof value !== "string" || !value.trim() || /[\p{Cc}\p{Cf}\p{Zl}\p{Zp}]/u.test(value)) {
    throw new Error("Invalid CLIProxyAPI display name");
  }
  return value.trim();
}
function tokenLimit(value, fallback) {
  if (value == null)
    return fallback;
  if (typeof value !== "number" || !Number.isSafeInteger(value) || value <= 0) {
    throw new Error("Invalid CLIProxyAPI token limit");
  }
  return value;
}
function selectModalities(value) {
  if (value == null)
    return ["text"];
  if (!Array.isArray(value) || !value.every((item) => typeof item === "string")) {
    throw new Error("Invalid CLIProxyAPI modality list");
  }
  return modalities.filter((modality) => value.includes(modality));
}
function selectEfforts(value) {
  if (value == null)
    return [];
  if (!Array.isArray(value))
    throw new Error("Invalid CLIProxyAPI reasoning list");
  const advertised = value.map((item) => record(item).effort);
  if (!advertised.every((effort) => typeof effort === "string")) {
    throw new Error("Invalid CLIProxyAPI reasoning effort");
  }
  return efforts.filter((effort) => advertised.includes(effort));
}
function sortModels(models) {
  return models.sort((left, right) => left.id < right.id ? -1 : Number(left.id > right.id));
}
function richCatalog(rows) {
  if (!Array.isArray(rows))
    throw new Error("Invalid CLIProxyAPI rich catalog");
  const seen = new Set;
  const models = [];
  for (const entry of rows) {
    const row = record(entry);
    const id = getID(row.slug, seen);
    if (row.visibility === "hide")
      continue;
    if (row.visibility != null && row.visibility !== "list")
      throw new Error("Invalid CLIProxyAPI model visibility");
    const contextWindow = tokenLimit(row.context_window, fallbackContext);
    const supported = selectEfforts(row.supported_reasoning_levels);
    const defaultEffort = supported.find((effort) => effort === row.default_reasoning_level);
    if (row.default_reasoning_level != null && typeof row.default_reasoning_level !== "string") {
      throw new Error("Invalid CLIProxyAPI reasoning default");
    }
    if (row.supports_tool_use != null && typeof row.supports_tool_use !== "boolean") {
      throw new Error("Invalid CLIProxyAPI tool capability");
    }
    models.push({
      id,
      name: nameOf(row.display_name, id),
      contextWindow,
      maxTokens: tokenLimit(row.max_tokens, Math.min(fallbackOutput, contextWindow)),
      input: selectModalities(row.input_modalities),
      output: selectModalities(row.output_modalities),
      efforts: supported,
      defaultEffort,
      tools: row.supports_tool_use ?? undefined
    });
  }
  return { mode: "rich", models: sortModels(models) };
}
function degradedCatalog(rows) {
  if (!Array.isArray(rows))
    throw new Error("Invalid CLIProxyAPI ID-only catalog");
  const seen = new Set;
  const models = rows.map((entry) => {
    const id = getID(record(entry).id, seen);
    return {
      id,
      name: `${id} (ID only)`,
      contextWindow: fallbackContext,
      maxTokens: fallbackOutput,
      input: ["text"],
      output: ["text"],
      efforts: []
    };
  });
  return { mode: "degraded", models: sortModels(models) };
}
async function fetchCatalog(connection, signal, fetcher) {
  const send = gatewayFetch(connection, fetcher);
  const timeout = AbortSignal.timeout(1e4);
  const init = { signal: signal ? AbortSignal.any([timeout, signal]) : timeout, headers: { accept: "application/json" } };
  const endpoint = `${connection.baseUrl}/models`;
  const rich = await send(`${endpoint}?client_version=cpa`, init);
  if (rich.ok) {
    const document = record(await rich.json());
    if (Object.hasOwn(document, "models"))
      return checkedCatalog(richCatalog(document.models), connection.apiKey);
    if (!Array.isArray(document.data))
      throw new Error("Unrecognized CLIProxyAPI catalog");
  } else {
    await rich.body?.cancel();
    if (!unsupportedStatuses.includes(rich.status))
      throw new Error("CLIProxyAPI rich catalog request failed");
  }
  const plain = await send(endpoint, init);
  if (!plain.ok) {
    await plain.body?.cancel();
    throw new Error("CLIProxyAPI ID-only catalog request failed");
  }
  return checkedCatalog(degradedCatalog(record(await plain.json()).data), connection.apiKey);
}
function checkedCatalog(catalog, key) {
  if (catalog.models.some(({ id, name }) => id === key || name === key || name.includes(`Bearer ${key}`) || key.length >= 16 && (id.includes(key) || name.includes(key)))) {
    throw new Error("CLIProxyAPI catalog echoed its credential");
  }
  return catalog;
}
function encodeCache(catalog) {
  const rows = catalog.mode === "degraded" ? catalog.models.map(({ id }) => ({ id })) : catalog.models.map((model) => ({
    slug: model.id,
    display_name: model.name,
    context_window: model.contextWindow,
    max_tokens: model.maxTokens,
    input_modalities: model.input,
    output_modalities: model.output,
    supported_reasoning_levels: model.efforts.map((effort) => ({ effort })),
    default_reasoning_level: model.defaultEffort,
    supports_tool_use: model.tools
  }));
  return JSON.stringify({ version: 1, mode: catalog.mode, rows }) + `
`;
}
async function readCache(path, key) {
  try {
    const file = await open(path, constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK);
    try {
      const stat = await file.stat();
      if (!stat.isFile() || (stat.mode & 511) !== 384 || stat.uid !== process.getuid?.())
        return;
      const { version, mode, rows } = record(JSON.parse(await file.readFile("utf8")));
      if (version !== 1)
        return;
      if (mode === "rich")
        return checkedCatalog(richCatalog(rows), key);
      if (mode === "degraded")
        return checkedCatalog(degradedCatalog(rows), key);
    } finally {
      await file.close();
    }
  } catch {
    return;
  }
}
async function writeCache(directory, path, contents) {
  await mkdir(directory, { recursive: true, mode: 448 });
  const tempPath = join(directory, `.${randomUUID()}.tmp`);
  try {
    await writeFile(tempPath, contents, { flag: "wx", mode: 384 });
    await rename(tempPath, path);
  } finally {
    await rm(tempPath, { force: true });
  }
}
function createDiscovery(connection, cacheDir, fetcher) {
  const identity = createHash("sha256").update(connection.baseUrl).update("\x00").update(connection.apiKey).digest("hex");
  const path = join(cacheDir, `catalog-v1-${identity}.json`);
  let lastGood;
  let lastWritten;
  return async (signal) => {
    let catalog;
    try {
      catalog = await fetchCatalog(connection, signal, fetcher);
    } catch {
      signal?.throwIfAborted();
      const cached = lastGood ?? await readCache(path, connection.apiKey);
      signal?.throwIfAborted();
      if (!cached)
        throw new Error("CLIProxyAPI catalog unavailable and no private cache is readable");
      lastGood = cached;
      return { catalog: cached, source: "cache" };
    }
    signal?.throwIfAborted();
    lastGood = catalog;
    const contents = encodeCache(catalog);
    try {
      if (contents !== lastWritten) {
        await writeCache(cacheDir, path, contents);
        lastWritten = contents;
      }
      return { catalog, source: "live" };
    } catch {
      return { catalog, source: "live", cacheWriteFailed: true };
    }
  };
}
function warnOnDiscoveryStatus(label) {
  let previous;
  return (status) => {
    const notes = [];
    if (!status)
      notes.push("catalog unavailable and no private cache is readable");
    if (status?.source === "cache")
      notes.push("using the cached catalog");
    if (status?.catalog.mode === "degraded")
      notes.push("degraded catalog (IDs only)");
    if (status?.cacheWriteFailed)
      notes.push("could not update the private catalog cache");
    const message = notes.join(". ");
    if (message && message !== previous)
      console.warn(`[${label}] ${message}.`);
    previous = message;
  };
}

// src/index.ts
var packageName = "opencode-cliproxyapi";
var sdkPackage = `aisdk:${packageName}`;
var zero = 0;
function toModel(providerId, row, mode) {
  const id = row.id;
  return {
    id,
    modelID: id,
    providerID: providerId,
    name: row.name,
    capabilities: { tools: row.tools ?? mode === "rich", input: row.input, output: row.output },
    limit: { context: row.contextWindow, output: row.maxTokens },
    cost: [{ input: zero, output: zero, cache: { read: zero, write: zero } }],
    time: { released: 0 },
    status: "active",
    enabled: true,
    body: row.defaultEffort === undefined ? undefined : { reasoning_effort: row.defaultEffort },
    variants: row.efforts.map((effort) => ({
      id: effort,
      body: { reasoning_effort: effort }
    }))
  };
}
function intervalMs(option) {
  if (option === undefined)
    return 300000;
  if (typeof option !== "number" || !Number.isFinite(option) || option <= 0 || option > 2147483) {
    throw new Error("Invalid refreshIntervalSeconds option");
  }
  return Math.max(60000, Math.round(option * 1000));
}
var src_default = Plugin.define({
  id: packageName,
  async setup(ctx) {
    const options = ctx.options;
    const connection = resolveConnection(options);
    const id = providerID(options.providerId);
    const name = stringOption(options.name, "name") ?? "CLIProxyAPI";
    const interval = intervalMs(options.refreshIntervalSeconds);
    const cacheDir = stringOption(options.cacheDir, "cacheDir") ?? defaultCacheDir(packageName);
    const discover = createDiscovery(connection, cacheDir);
    const report = warnOnDiscoveryStatus(packageName);
    const lifetime = new AbortController;
    const instance = randomUUID2();
    await ctx.aisdk.hook("sdk", (event) => {
      if (event.package !== packageName)
        return;
      const sdk = createOpenAICompatible({
        name: id,
        baseURL: connection.baseUrl,
        fetch: gatewayFetch(connection, event.options.fetch)
      });
      event.sdk = { languageModel: sdk.chatModel };
    }, { providerID: id });
    let catalog;
    try {
      const initial = await discover(lifetime.signal);
      report(initial);
      catalog = initial.catalog;
    } catch {
      report();
    }
    await ctx.provider.transform((editor) => {
      const snapshot = catalog;
      if (!snapshot)
        return;
      editor.update(id, (provider) => {
        provider.name = name;
        provider.activation = "enabled";
        provider.package = sdkPackage;
        provider.canonical = undefined;
        provider.integrationID = undefined;
        provider.headers = undefined;
        provider.body = undefined;
        provider.settings = { baseURL: connection.baseUrl, cpaDiscoveryInstance: instance };
      });
      editor.models.set(id, snapshot.models.map((model) => toModel(id, model, snapshot.mode)));
    });
    let published = JSON.stringify(catalog);
    let pending;
    const refresh = () => {
      pending ??= (async () => {
        try {
          const result = await discover(lifetime.signal);
          if (lifetime.signal.aborted)
            return;
          report(result);
          const signature = JSON.stringify(result.catalog);
          if (signature === published)
            return;
          catalog = result.catalog;
          try {
            await ctx.provider.reload();
            published = signature;
          } catch {
            console.warn(`[${packageName}] could not reload the model registry. Retrying on the next refresh.`);
          }
        } catch {
          if (!lifetime.signal.aborted)
            report();
        }
      })().finally(() => {
        pending = undefined;
      });
      return pending;
    };
    const timer = setInterval(refresh, interval);
    timer.unref();
    return async () => {
      clearInterval(timer);
      lifetime.abort();
      await pending;
    };
  }
});
export {
  src_default as default
};
